import React, { useState } from "react";
import { FiEdit } from "react-icons/fi";
import { FaTrash } from "react-icons/fa";
import AdminEditProduct from "./AdminEditProduct";

export default function AdminProductList() {
  const [editModalOpen, setEditModalOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);

  const products = [
    { id: 1, name: "Product Name", price: "100", stocks: 100 },
    { id: 2, name: "Product Name", price: "100", stocks: 100 },
    { id: 3, name: "Product Name", price: "100", stocks: 100 },
    { id: 4, name: "Product Name", price: "100", stocks: 100 },
    { id: 5, name: "Product Name", price: "100", stocks: 100 },
  ];

  const openEdit = (product) => {
    setSelectedProduct(product);
    setEditModalOpen(true);
  };

  return (
    <div className="w-full px-6 py-4">
      <div
        className="rounded-2xl shadow-md p-4 overflow-hidden"
        style={{ backgroundColor: "#FFFFFF", border: "3px solid #E1E1E1" }}
      >
        <table className="w-full text-left">
          <thead>
            <tr className="text-black font-bold">
              <th className="p-3">ID</th>
              <th className="p-3">PRODUCT NAME</th>
              <th className="p-3">PRICE</th>
              <th className="p-3">STOCKS</th>
              <th className="p-3 text-right">ACTIONS</th>
            </tr>
          </thead>

          <tbody>
            {products.map((p, index) => (
              <tr
                key={index}
                className="rounded-xl"
                style={{
                  backgroundColor: "#E1E1E1",
                  borderBottom: "10px solid white",
                }}
              >
                <td className="p-3">{p.id}</td>
                <td className="p-3">{p.name}</td>
                <td className="p-3">{p.price}</td>
                <td className="p-3 font-bold">{p.stocks}</td>

                <td className="p-3">
                  <div className="flex justify-end space-x-5">
                    <FiEdit
                      size={20}
                      color="#000000"
                      className="cursor-pointer hover:scale-110 transition"
                      onClick={() => openEdit(p)}
                    />
                    <FaTrash
                      size={20}
                      color="#FF0000"
                      className="cursor-pointer hover:scale-110 transition"
                    />
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Edit Modal */}
      <AdminEditProduct
        isOpen={editModalOpen}
        onClose={() => setEditModalOpen(false)}
        product={selectedProduct}
      />
    </div>
  );
}
